INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988225315388162049', '1987710301241778177', '2025-11-11 20:40:29', '1988487570277195777', '2025-11-12 14:03:02', 0, 2, '重庆地陪日记📚\n綦江走不走？哈哈哈\n被同一位客户预定的第三天啦[萌萌哒R]\n客户是一位重庆资深玩家👦🏻\n在市区景点打卡完毕后🔚\n选择去王齐铭歌🎶里的綦江看看👀\n跟随歌词我们一路去吃了沙手米粉😋\n找到了百步梯🛤️文昌巷\n感受着重庆山城人民的慢生活👍🏻\n', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/11/5aad975c-5298-4197-aec6-3ccee9b26e00.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/11/4a69e0ee-c27f-43e9-8c19-db2374be4006.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/11/41aedc67-8026-4bc7-8751-350999c0b5d3.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/11/410da38c-1513-4266-a8a7-2a29fec75809.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/11/c5869b76-7f8a-453b-a9a9-d88600e02c1f.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/11/b43ca903-995b-41b7-b4e6-923fab5a2c29.jpg\"]', '1987710301241778177', 1, '1', 0, 0, 0, '重庆市', 'image');
INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988447719129538562', '1988167384630198273', '2025-11-12 11:24:14', '1987519030707527682', '2025-11-26 23:58:02', 0, 3, '爬山 徒步 citywalk 飞拉达 电动越野摩托\n户外都超爱的\n在重庆不知道怎么玩\n根本不可能', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/5b8eb272-8557-4a8d-865a-2ca57cac0afd.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/73841763-caca-4fdc-84a8-6b2e4d582e12.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/a7b067c2-c118-4f6d-b8d0-48fc23a442d5.jpg\"]', '1988167384630198273', 1, '1', 1, 0, 0, '重庆市', 'image');
