INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988483117264330753', '1987710301241778177', '2025-11-12 13:44:54', NULL, '2025-11-12 13:44:54', 0, 0, '今天接待的小姐姐👧🏻\n想要悠闲地citywalk🌁#重逢便是庆[话题]#\n我们从下浩里→龙门浩→开埠公园\n累了就去吃地道重庆火锅🍲\n我们相见恨晚 一路上说不完的话题\n整体下来惬意又愉快😎', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/7f1583d4-b7e9-441d-8e39-2540a847a93d.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/cceafa52-e7bc-488c-918b-b42a70a9f137.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/3d1d6deb-769a-421a-a2b2-96911d1f1cd4.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/97413d88-4768-4de6-bb18-ff908c3245c1.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/f635dee5-a722-4188-b681-187608953d93.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/a5f68c2b-6aa2-4179-9b2a-137d20f29d06.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/f21a2c23-03a8-4c1a-b8ab-6676c2721df3.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/afa78ad6-b28f-4d0e-a5cf-eedd013276ac.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/15d82ac5-cf3b-4aef-b621-afda54902ec1.jpg\"]', '1987710301241778177', 1, '1', 0, 0, 0, '重庆市', 'image');
INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988551022853152770', '1988550061329932289', '2025-11-12 18:14:44', NULL, '2025-11-12 18:14:44', 0, 0, '朋友式地陪/导游+00后大学生\n不包含交通费和出去游玩的门票钱\n两种方式可选：\n\n1️⃣朋友式导游：会精心制作攻略，能全程陪伴一同游玩，将情绪价值拉满，尤其适合来重庆旅游的朋友，致力于带你用最少的钱逛最多的景点。\n\n2️⃣朋友式搭子：适合在本地的兄弟姐妹，可以一起去探店打卡、参观博物馆、聊天吹牛、city walk、shoping、提供穿搭建议、live house、去图书馆/书城看书……\n\n可选择小时或包天，自由灵活搭配。\n指定景点有门票需要自行承担。\n\n关于本人：00后男大，性格热情、友善，善于沟通，能够提供丰富情绪价值，不混任何圈子，不会胡乱加价，该多少价格就是多少价格，绝无隐形消费，如果有指定去的景点需要门票则需你自理，没有复杂的规矩，在家比较清闲所以想找点事做。\n\n免责声明：非专业导游介意勿扰，我会尽我最大努力把路线规划合理，主要是陪伴一起游玩，提供情绪价值！', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/12/352f34f0-93fc-45fe-aa99-41e9bfbc3a5e.jpg\"]', '1988550061329932289', 1, '1', 0, 0, 0, '重庆市', 'image');
