INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988801425247232001', '1988800077747380226', '2025-11-13 10:49:45', '1993935400932364289', '2025-11-27 17:12:25', 0, 8, '重庆陪玩 20岁，163，49kg。美术生大三\n1️⃣熟悉各大景点、路线、打卡点、近路。会制定路线\n无纹身无整。性格温柔。唱歌好听，会🍺\n2️⃣喜欢王者、剧本杀、密室、麻将、钓鱼、重庆导游、唱歌、聚餐、逛街、桌游、打卡网红景点、爬山、运动、看电影、剧本杀、下午茶等', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/0b8927bf-60ae-4683-80eb-19dc45624831.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/f9b896df-807e-44a1-8c19-8174db604678.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/cf927004-c868-41e6-8907-4f518e10f3de.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/e1587142-c5aa-4f60-90d1-c7fdda3b4af4.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/f8710c1f-813d-4df6-b612-bc8713be3719.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/c05ac2ff-2518-4eef-9aaa-87d97c2ccc63.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/958d7932-5e6f-46b9-adad-c56244d78cc3.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/2203f6c3-cac4-49f9-be98-9c671bb99bb0.jpg\"]', '1988800077747380226', 1, '1', 2, 6, 0, '重庆市', 'image');
