INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988881246090354689', '1988878239453863938', '2025-11-13 16:06:55', '1994389502975963137', '2025-11-28 20:57:13', 0, 1, '朋友式地陪/导游+00后美术老师\n可包含交通费和不包含出去游玩的门票钱\n①朋友式导游：会精心制作攻略，能全程陪伴一同游玩，将情绪价值拉满，尤其适合来重庆旅游的朋友，致力于带你用最少的钱逛最多的景点。\n2朋友式搭子：适合在本地的兄弟姐妹，可以一起去探店打卡、参观博物馆、聊天吹牛、city walk、shoping、提供穿搭建议、livehouse、去图书馆/书城看书….\n可选择小时或包天，自由灵活搭配。\n\n关于本人：00后美术老师，180，小小帅，正在健身，放心我拍照技术杠杠的，性格热情、友善，善于沟通，能够提供丰富情绪价值，不混任何圈子，不会胡乱加价，该多少价格就是多少价格，绝无隐形消费，如果有指定去的景点需要门票则需你自理，没有复杂的规矩，在家比较清闲所以想找点事做。\n\n免责声明：非专业导游介意勿扰，我会尽我最大努力把路线规划合理丰要是陪伴一起游玩，提供情绪价值，让大家能玩的开心', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/5cee4c5d-d001-4985-bd38-28e1c1669abb.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/e5c84139-048e-4ac4-8203-526e2f4a1f4a.png\"]', '1988878239453863938', 1, '1', 0, 1, 0, '重庆市', 'image');
INSERT INTO `article` (`id`, `creator`, `create_time`, `modifyer`, `modify_time`, `del_flag`, `version`, `content`, `img`, `user_id`, `open`, `recommend`, `like_count`, `comment_count`, `sort`, `city`, `type`) VALUES ('1988902656825286657', '1988901202433597441', '2025-11-13 17:32:00', NULL, '2025-11-13 17:32:00', 0, 0, '🔥【重庆私人定制游】本地老司机带路，1对1VIP耍嗨山城！\n\n👫 一人独行·情侣甜蜜·闺蜜疯玩·兄弟扎起·全家欢乐——统统安排！\n\n🚗 为什么选我们？\n✅ 地道重庆崽儿——不是导游，是你在这儿的“兄弟伙/姐妹淘”，带你去游客找不到的卡卡角角！\n✅ 千人千面定制——根据你们的需求/口味/体力，量身设计路线，拒绝模板化打卡！\n✅ 全程轻松无坑——接送+陪玩+拍照+砍价+避雷，你只管耍，其他交给我！\n\n📌 专属套餐推荐\n💑 情侣浪漫版：洪崖洞夜景私藏机位+江景餐厅+爱情天台锁同心锁\n👯 闺蜜暴走版：小众文创园拍照+网红下午茶+解放碑夜市淘货\n🍻 兄弟江湖版：防空洞老火锅+夜啤酒烧烤摊+朝天门码头夜游\n👨👩👧👦 家庭休闲版：长江索道VIP通道+山城步道慢逛+非遗茶馆体验\n\n💬 “来重庆，像本地人一样生活！”\n👉 私信发送【人数+兴趣】，立刻获取你的《重庆专属玩法方案》❗\n（附赠：24小时在线咨询+紧急救援电话+雨天备选方案🌧️）', '[\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/76240520-89b6-4c95-97dd-f8a5e7cd9cd7.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/3e9a86eb-9dbb-4232-a881-0543b6e8de44.jpg\",\"https://yanjian-1326741559.cos.ap-chongqing.myqcloud.com/2025/11/13/2f42daa4-efc6-4b75-8459-45c4738977c5.jpg\"]', '1988901202433597441', 1, '1', 0, 0, 0, '重庆市', 'image');
